-- RoadToSmartBaking: create four content tables and import the bundled catalog.
-- Run this ENTIRE file in your intended PostgreSQL database as a schema owner.
-- No database is created or selected by this script. Check the connection first.
-- Existing records are skipped, including their edits, drafts and visibility.
-- Source: c9b69703636a77f89c424ae4fa56ac10d18a165f36a2909fd710fa34ef7d2b13
-- 43 shops (42 public, Desdott hidden), 63 Italian stories. No English translations are fabricated.
-- Image files must also be deployed from this project's public directory.
-- This does NOT configure application credentials, staff login or Amplify.

BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '120s';
CREATE SCHEMA IF NOT EXISTS road_to_smartbaking;
SET LOCAL search_path TO road_to_smartbaking, pg_catalog;
SELECT pg_advisory_xact_lock(hashtext('rtsm:catalog-import:road_to_smartbaking'));

DO $install$
DECLARE existing_count integer;
BEGIN
  SELECT count(*) INTO existing_count FROM pg_catalog.pg_class c
  JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace
  WHERE n.nspname='road_to_smartbaking' AND c.relkind IN ('r','p')
    AND c.relname IN ('rtsm_shop','rtsm_story','rtsm_requests','rtsm_reports');
  IF existing_count=0 THEN
    EXECUTE $rtsm_3b7dd3f6ce6930f7$-- Fresh four-table installation. Run through scripts/setup-shared-db.mjs.


-- This table contains approved shop records. Suspended records are retained.
CREATE TABLE rtsm_shop (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    slug text NOT NULL UNIQUE CHECK (btrim(slug) <> ''),
    name text NOT NULL CHECK (btrim(name) <> ''),
    category text NOT NULL CHECK (category IN ('pizza', 'restaurant', 'qsr', 'bakery', 'hotel', 'other')),
    address text NOT NULL CHECK (btrim(address) <> ''),
    city text NOT NULL CHECK (btrim(city) <> ''),
    country text NOT NULL CHECK (btrim(country) <> ''),
    latitude double precision NOT NULL CHECK (latitude BETWEEN -90 AND 90),
    longitude double precision NOT NULL CHECK (longitude BETWEEN -180 AND 180),
    description_it text,
    description_en text,
    oven_model text,
    website_url text,
    image_url text,
    image_alt_it text,
    image_alt_en text,
    verified_at timestamptz NOT NULL,
    approved_at timestamptz NOT NULL CHECK (approved_at >= verified_at),
    published_at timestamptz CHECK (published_at >= approved_at),
    suspended_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CHECK (suspended_at IS NULL OR (published_at IS NOT NULL AND suspended_at >= published_at))
);

CREATE TABLE rtsm_story (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    slug text NOT NULL CHECK (btrim(slug) <> ''),
    language text NOT NULL CHECK (language IN ('it', 'en')),
    title text NOT NULL CHECK (btrim(title) <> ''),
    summary text NOT NULL CHECK (btrim(summary) <> ''),
    category text NOT NULL CHECK (btrim(category) <> ''),
    blocks jsonb NOT NULL DEFAULT '[]' CHECK (jsonb_typeof(blocks) = 'array'),
    cover_image_url text,
    cover_image_alt text,
    source_url text,
    source_published_at timestamptz,
    approved_at timestamptz,
    published_at timestamptz,
    expires_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (slug, language),
    CHECK (published_at IS NULL OR (approved_at IS NOT NULL AND published_at >= approved_at)),
    CHECK (expires_at IS NULL OR (published_at IS NOT NULL AND expires_at > published_at))
);

-- Contact information and review notes are private staff data.
CREATE TABLE rtsm_requests (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    business_name text NOT NULL CHECK (btrim(business_name) <> ''),
    category text NOT NULL CHECK (category IN ('pizza', 'restaurant', 'qsr', 'bakery', 'hotel', 'other')),
    address text NOT NULL CHECK (btrim(address) <> ''),
    city text NOT NULL CHECK (btrim(city) <> ''),
    country text NOT NULL CHECK (btrim(country) <> ''),
    oven_model text NOT NULL CHECK (btrim(oven_model) <> ''),
    website_url text,
    contact_name text NOT NULL CHECK (btrim(contact_name) <> ''),
    contact_email text NOT NULL CHECK (btrim(contact_email) <> ''),
    notes text,
    review_note text,
    status text NOT NULL DEFAULT 'submitted'
        CHECK (status IN ('submitted', 'in_review', 'needs_info', 'approved', 'declined')),
    shop_id uuid REFERENCES rtsm_shop (id),
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CHECK ((status = 'approved') = (shop_id IS NOT NULL))
);

CREATE INDEX rtsm_requests_queue_idx ON rtsm_requests (status, created_at DESC);
CREATE INDEX rtsm_requests_shop_idx ON rtsm_requests (shop_id);



-- Preserve fixture details that have no dedicated database column.
ALTER TABLE rtsm_shop ADD COLUMN IF NOT EXISTS frontend_source jsonb;
ALTER TABLE rtsm_story ADD COLUMN IF NOT EXISTS frontend_source jsonb;


CREATE TABLE rtsm_reports (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  shop_id uuid NOT NULL REFERENCES rtsm_shop(id),
  reason text NOT NULL CHECK (reason IN ('incorrect', 'closed', 'inappropriate', 'other')),
  details text NOT NULL CHECK (length(btrim(details)) BETWEEN 1 AND 2000),
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX rtsm_reports_queue_idx ON rtsm_reports(created_at DESC);



ALTER TABLE rtsm_shop
  ADD COLUMN draft_payload jsonb,
  ADD COLUMN draft_revision uuid,
  ADD COLUMN draft_saved_at timestamptz,
  ADD CONSTRAINT rtsm_shop_draft_consistent CHECK (
    (draft_payload IS NULL AND draft_revision IS NULL AND draft_saved_at IS NULL) OR
    (draft_payload IS NOT NULL AND jsonb_typeof(draft_payload) = 'object'
      AND draft_revision IS NOT NULL AND draft_saved_at IS NOT NULL));

ALTER TABLE rtsm_story
  ADD COLUMN draft_payload jsonb,
  ADD COLUMN draft_revision uuid,
  ADD COLUMN draft_saved_at timestamptz,
  ADD CONSTRAINT rtsm_story_draft_consistent CHECK (
    (draft_payload IS NULL AND draft_revision IS NULL AND draft_saved_at IS NULL) OR
    (draft_payload IS NOT NULL AND jsonb_typeof(draft_payload) = 'object'
      AND draft_revision IS NOT NULL AND draft_saved_at IS NOT NULL));
$rtsm_3b7dd3f6ce6930f7$;
  ELSIF existing_count<>4 THEN
    RAISE EXCEPTION 'Only some RTSM tables exist. No import applied: review the existing schema first.';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='road_to_smartbaking' AND table_name='rtsm_shop' AND column_name='draft_payload')
     OR NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='road_to_smartbaking' AND table_name='rtsm_story' AND column_name='draft_payload') THEN
    RAISE EXCEPTION 'Existing RTSM schema needs the embedded-draft upgrade. No import applied.';
  END IF;
END
$install$;

